CREATE OR REPLACE FUNCTION private.base_validate(c jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE k text;r jsonb;x jsonb;seen text[];id text;rules jsonb;BEGIN IF c IS NULL OR jsonb_typeof(c)<>'object' OR length(c::text)>2000000 THEN RAISE EXCEPTION 'Cấu hình không hợp lệ.';END IF;FOREACH k IN ARRAY ARRAY['units','titles','memberships','defaults','bundles','grants','bindings'] LOOP IF jsonb_typeof(c->k) IS DISTINCT FROM 'array' OR jsonb_array_length(c->k)>5000 THEN RAISE EXCEPTION 'Thiếu danh sách %.',k;END IF;IF EXISTS(SELECT 1 FROM jsonb_array_elements(c->k) a WHERE jsonb_typeof(a)<>'object' OR coalesce(a->>'id','')='') OR EXISTS(SELECT 1 FROM jsonb_array_elements(c->k) a GROUP BY a->>'id' HAVING count(*)>1) THEN RAISE EXCEPTION 'ID thiếu hoặc trùng trong %.',k;END IF;END LOOP;
FOR r IN SELECT value FROM jsonb_array_elements(c->'units') LOOP IF coalesce(trim(r->>'name'),'')='' OR coalesce(r->>'kind','')<>ALL(ARRAY['block','department','team']) THEN RAISE EXCEPTION 'Đơn vị không hợp lệ.';END IF;seen:=ARRAY[r->>'id'];id:=nullif(r->>'parent_id','');WHILE id IS NOT NULL LOOP IF id=ANY(seen) THEN RAISE EXCEPTION 'Cơ cấu bị vòng lặp.';END IF;seen:=seen||id;SELECT value INTO x FROM jsonb_array_elements(c->'units') WHERE value->>'id'=id;IF x IS NULL THEN RAISE EXCEPTION 'Đơn vị cha không tồn tại.';END IF;id:=nullif(x->>'parent_id','');END LOOP;IF r->>'kind'='block' AND nullif(r->>'parent_id','') IS NOT NULL THEN RAISE EXCEPTION 'Khối không có đơn vị cha.';END IF;IF r->>'kind'<>'block' AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(c->'units') a WHERE a->>'id'=r->>'parent_id' AND a->>'kind'=CASE WHEN r->>'kind'='team' THEN 'department' ELSE 'block' END) THEN RAISE EXCEPTION 'Cấp đơn vị cha không hợp lệ.';END IF;END LOOP;
FOR r IN SELECT value FROM jsonb_array_elements(c->'titles') LOOP IF coalesce(trim(r->>'name'),'')='' THEN RAISE EXCEPTION 'Chức danh thiếu tên.';END IF;END LOOP;
FOR r IN SELECT value FROM jsonb_array_elements(c->'memberships') UNION ALL SELECT value FROM jsonb_array_elements(c->'grants') UNION ALL SELECT value FROM jsonb_array_elements(c->'bindings') LOOP IF NOT EXISTS(SELECT 1 FROM profiles WHERE id::text=r->>'user_id') THEN RAISE EXCEPTION 'Nhân sự không tồn tại.';END IF;IF nullif(r->>'starts_at','') IS NOT NULL THEN PERFORM (r->>'starts_at')::timestamptz;END IF;IF nullif(r->>'ends_at','') IS NOT NULL AND (r->>'ends_at')::timestamptz<=coalesce(nullif(r->>'starts_at','')::timestamptz,now()) AND coalesce((r->>'active')::boolean,false) THEN RAISE EXCEPTION 'Thời hạn không hợp lệ.';END IF;END LOOP;
FOR r IN SELECT value FROM jsonb_array_elements(c->'memberships') LOOP IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(c->'units') a WHERE a->>'id'=r->>'unit_id') OR (nullif(r->>'title_id','') IS NOT NULL AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(c->'titles') a WHERE a->>'id'=r->>'title_id')) THEN RAISE EXCEPTION 'Phân công sai đơn vị/chức danh.';END IF;END LOOP;
FOR r IN SELECT value FROM jsonb_array_elements(c->'defaults') LOOP IF (nullif(r->>'unit_id','') IS NULL)=(nullif(r->>'title_id','') IS NULL) OR (nullif(r->>'unit_id','') IS NOT NULL AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(c->'units') a WHERE a->>'id'=r->>'unit_id')) OR (nullif(r->>'title_id','') IS NOT NULL AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(c->'titles') a WHERE a->>'id'=r->>'title_id')) THEN RAISE EXCEPTION 'Nguồn quyền mặc định không hợp lệ.';END IF;END LOOP;
FOR r IN SELECT value FROM jsonb_array_elements(c->'bindings') LOOP IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(c->'bundles') a WHERE a->>'id'=r->>'bundle_id') THEN RAISE EXCEPTION 'Bộ quyền không tồn tại.';END IF;END LOOP;
rules:=coalesce((SELECT jsonb_agg(a) FROM (SELECT value a FROM jsonb_array_elements(c->'grants') UNION ALL SELECT q FROM jsonb_array_elements(c->'defaults') d CROSS JOIN LATERAL jsonb_array_elements(d->'rules') q UNION ALL SELECT q FROM jsonb_array_elements(c->'bundles') b CROSS JOIN LATERAL jsonb_array_elements(b->'rules') q)s),'[]');FOR r IN SELECT value FROM jsonb_array_elements(rules) LOOP IF NOT EXISTS(SELECT 1 FROM base_permission_catalog WHERE key=r->>'permission') OR coalesce(r->>'effect','')<>ALL(ARRAY['ALLOW','DENY']) THEN RAISE EXCEPTION 'Quyền hoặc quyết định không hợp lệ.';END IF;IF coalesce((r->>'active')::boolean,false) AND NOT private.base_supported(r->>'permission') THEN RAISE EXCEPTION 'Quyền này chưa được tích hợp đầy đủ; chỉ được lưu bản nháp.';END IF;IF coalesce(r->>'scope','native')<>(CASE WHEN r->>'permission' LIKE 'biz.crm_%' THEN 'own' ELSE 'native' END) THEN RAISE EXCEPTION 'Phạm vi chưa được hỗ trợ.';END IF;IF nullif(r->>'starts_at','') IS NOT NULL THEN PERFORM (r->>'starts_at')::timestamptz;END IF;IF nullif(r->>'ends_at','') IS NOT NULL THEN PERFORM (r->>'ends_at')::timestamptz;END IF;END LOOP;END $$;
CREATE OR REPLACE FUNCTION private.base_fingerprint() RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT md5(coalesce((SELECT string_agg(jsonb_build_object('id',r.id,'status',r.status)::text,'|' ORDER BY r.id) FROM profiles r),'')||coalesce((SELECT string_agg(row_to_json(r)::text,'|' ORDER BY row_to_json(r)::text) FROM app_roles r),'')||coalesce((SELECT string_agg(row_to_json(r)::text,'|' ORDER BY row_to_json(r)::text) FROM user_roles r),'')||coalesce((SELECT string_agg(row_to_json(r)::text,'|' ORDER BY row_to_json(r)::text) FROM user_permission_overrides r),'')||coalesce((SELECT string_agg(row_to_json(r)::text,'|' ORDER BY row_to_json(r)::text) FROM biz_appointments r),'')||coalesce((SELECT string_agg(row_to_json(r)::text,'|' ORDER BY row_to_json(r)::text) FROM crm_access_grants r),'')) $$;
CREATE OR REPLACE FUNCTION private.base_impact(c jsonb) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE u record;b jsonb;a jsonb;diff jsonb;result jsonb:='[]';BEGIN FOR u IN SELECT id,full_name FROM profiles LOOP b:=private.base_effective(u.id,private.base_config());a:=private.base_effective(u.id,c);SELECT coalesce(jsonb_agg(jsonb_build_object('key',x->>'key','label',x->>'label','before',y,'after',x)),'[]') INTO diff FROM jsonb_array_elements(a)x JOIN jsonb_array_elements(b)y ON x->>'key'=y->>'key' WHERE x IS DISTINCT FROM y;IF jsonb_array_length(diff)>0 THEN result:=result||jsonb_build_array(jsonb_build_object('user_id',u.id,'name',u.full_name,'changes',diff));END IF;END LOOP;RETURN result;END $$;
CREATE OR REPLACE FUNCTION public.base_org_preview(_revision bigint,_config jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE i uuid;impact jsonb;BEGIN IF NOT private.base_org_admin() THEN RAISE EXCEPTION 'Không có quyền quản trị.';END IF;PERFORM pg_advisory_xact_lock(hashtext('base_org'));IF coalesce((SELECT revision FROM base_org_state WHERE id),0)<>_revision THEN RAISE EXCEPTION 'Cấu hình đã thay đổi; vui lòng tải lại.';END IF;PERFORM private.base_validate(_config);impact:=private.base_impact(_config);INSERT INTO base_permission_previews(actor_id,revision,config,baseline,impact) VALUES(auth.uid(),_revision,_config,private.base_fingerprint(),impact) RETURNING id INTO i;RETURN jsonb_build_object('id',i,'revision',_revision,'impact',impact,'expires_at',now()+interval '10 minutes');END $$;
CREATE OR REPLACE FUNCTION public.base_org_apply(_preview uuid,_confirmation text) RETURNS bigint LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p base_permission_previews;v bigint;old jsonb;impact jsonb;BEGIN IF NOT private.base_org_admin() OR _confirmation IS DISTINCT FROM 'ÁP DỤNG PHÂN QUYỀN' THEN RAISE EXCEPTION 'Không có quyền hoặc thiếu xác nhận.';END IF;PERFORM pg_advisory_xact_lock(hashtext('base_org'));SELECT * INTO p FROM base_permission_previews WHERE id=_preview AND actor_id=auth.uid() FOR UPDATE;IF NOT FOUND OR p.expires_at<=now() OR p.applied_at IS NOT NULL THEN RAISE EXCEPTION 'Bản xem trước hết hạn hoặc đã được áp dụng.';END IF;v:=coalesce((SELECT revision FROM base_org_state WHERE id),0);old:=private.base_config();IF v<>p.revision OR p.baseline<>private.base_fingerprint() THEN RAISE EXCEPTION 'Nguồn quyền/nhân sự đã thay đổi; cần xem trước lại.';END IF;PERFORM private.base_validate(p.config);impact:=private.base_impact(p.config);IF impact IS DISTINCT FROM p.impact THEN RAISE EXCEPTION 'Quyền đã đổi theo hiệu lực; cần xem trước lại.';END IF;INSERT INTO base_org_state(id,revision,config) VALUES(true,v+1,p.config) ON CONFLICT(id) DO UPDATE SET revision=v+1,config=p.config,updated_at=now();INSERT INTO base_permission_events(actor_id,action,before_revision,after_revision,before_data,after_data,impact) VALUES(auth.uid(),'apply',v,v+1,old,p.config,impact);UPDATE base_permission_previews SET applied_at=now() WHERE id=p.id;RETURN v+1;END $$;
DO $$ DECLARE r record;BEGIN FOR r IN SELECT p.oid::regprocedure fn FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE (n.nspname='private' AND p.proname IN ('base_validate','base_fingerprint','base_impact')) OR (n.nspname='public' AND p.proname IN ('base_org_preview','base_org_apply')) LOOP EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC,anon',r.fn);IF r.fn::text LIKE 'private.%' THEN EXECUTE format('REVOKE ALL ON FUNCTION %s FROM authenticated',r.fn);ELSE EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO authenticated,service_role',r.fn);END IF;END LOOP;END $$;